
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_revtpss_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_revtpss", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.479844520624302e-02, -5.427199007742484e-02, -5.350598353364211e-02, -5.238538289534993e-02, -5.073275294884787e-02, -4.826619236454870e-02, -4.452259549662724e-02, -3.873638582660448e-02, -2.986635628149036e-02, -1.827019100762680e-02, -1.165803662963345e-02, -3.852455476481689e-02, -4.641572752681960e-02, -3.377323180871696e-02, -1.955784580632534e-02, -5.862681198666053e-03, -3.892952098785816e-04, -1.959969985767036e-06, -7.007995993676248e-10, -9.035471209498246e-15]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


